/*setNewPODelete_Item5*/
UPDATE ICOMIVHD HD SET HD.STATUS = DECODE((SELECT NVL(COUNT(*),0) FROM ICOMIVDT WHERE BUYER = HD.BUYER AND INV_NO = HD.INV_NO AND STATUS != 'D'), 0, 'D','R'), HD.INV_AMT = (SELECT NVL(SUM(DT.ITEM_AMT),0) FROM ICOMIVDT DT WHERE HD.BUYER = DT.BUYER AND HD.INV_NO = DT.INV_NO AND DT.STATUS != 'D'), HD.INV_TAX_RATE_1 = 0.1, HD.INV_TAX_AMT_1 = (SELECT NVL(TRUNC(SUM(DT.ITEM_AMT) * 0.1, 0),0) FROM ICOMIVDT DT WHERE HD.BUYER = DT.BUYER AND HD.INV_NO = DT.INV_NO AND DT.STATUS != 'D'), HD.INV_TTL_AMT = (SELECT NVL(SUM(DT.ITEM_AMT) + TRUNC(SUM(DT.ITEM_AMT) * 0.1, 0),0) FROM ICOMIVDT DT WHERE HD.BUYER = DT.BUYER AND HD.INV_NO = DT.INV_NO AND DT.STATUS != 'D'), HD.CHANGE_USER_ID = #{st_user_id}, HD.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), HD.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS') WHERE HD.BUYER = #{BUYER} AND HD.INV_NO IN (SELECT DISTINCT INV_NO FROM ICOMIVDT WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO} AND PO_SEQ = #{PO_SEQ}
)


/*setNewGrDelChange_Item3*/
UPDATE ICOMGRDT
   SET STATUS         = 'D',
       SEND_DATE      = ' ',
       SEND_TIME      = ' ',
       CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD'),
       CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS'),
       CHANGE_USER_ID = #{st_user_id}
 WHERE BUYER   = #{BUYER}
   AND PO_NO   = #{PO_NO}
   AND PO_SEQ  = #{PO_SEQ}
   AND (AR_BILL_FLAG != 'Y' OR AP_BILL_FLAG != 'Y')
   AND STATUS != 'D'


		/*setNewGrDelChange_Item4*/
        UPDATE ICOMPODT
           SET GR_QTY  = NVL(GR_QTY,0) - NVL( #{GR_QTY1}  , 0)
         WHERE BUYER   = #{BUYER}
           AND PO_NO   = #{PO_NO}
           AND PO_SEQ  = #{PO_SEQ}


/*master.mpso.setNewGrDelChange_Item5*/
UPDATE ICOMIVDT A
   SET GR_QTY  = DECODE((SELECT B.PROCESS_TYPE FROM ICOMGRDT B
                          WHERE B.BUYER   = #{BUYER}
                            AND B.PO_NO   = #{PO_NO}
                            AND B.PO_SEQ  = #{PO_SEQ}
                            AND B.INV_NO  = A.INV_NO
                            AND B.INV_SEQ = A.INV_SEQ
                            AND ROWNUM = 1
                            ),'0',0,'G1',0, A.GR_QTY)
 WHERE BUYER   = #{BUYER}
   AND PO_NO   = #{PO_NO}
   AND PO_SEQ  = #{PO_SEQ}
   AND A.STATUS != 'D'
